    2: "twenty", 3: "thirty", 4: "forty", 5: "fifty",
    6: "sixty", 7: "seventy", 8: "eighty", 9: "ninety",
}


def _words(n):
    """Spell out a non-negative integer in (American) English words."""
    n = int(n)
    if n < 20:
        return _ONES[n]
    if n < 100:
        tens, rem = divmod(n, 10)
        return _TENS[tens] + ("-" + _ONES[rem] if rem else "")
    if n < 1000:
        hundreds, rem = divmod(n, 100)
        return _ONES[hundreds] + " hundred" + (" " + _words(rem) if rem else "")
    for value, name in ((10 ** 9, "billion"), (10 ** 6, "million"), (10 ** 3, "thousand")):
        if n >= value:
            high, rem = divmod(n, value)
            return _words(high) + " " + name + (" " + _words(rem) if rem else "")
    return str(n)


def _to_int(cents):
    """Coerce assorted numeric-ish inputs to an integer number of cents."""
    if isinstance(cents, bool):
        return int(cents)
    if isinstance(cents, int):
        return cents
    if isinstance(cents, float):
        return int(round(cents))
    if isinstance(cents, str):
        s = cents.strip().replace("$", "").replace(",", "")
        return int(round(float(s)))
    try:
        return int(round(float(cents)))
    except Exception:
        return 0


def price_label(cents):
    """Return a human-readable price label for an amount given in integer cents."""
    total = _to_int(cents)
    negative = total < 0
    total = abs(total)
    dollars, rem = divmod(total, 100)

    parts = []
    if dollars:
        parts.append(_words(dollars) + (" dollar" if dollars == 1 else " dollars"))
    if rem:
        parts.append(_words(rem) + (" cent" if rem == 1 else " cents"))

    if not parts:
        label = "zero dollars"
    else:
        label = " and ".join(parts)

    return ("negative " + label) if negative else label
