TENS = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy",
        "eighty", "ninety"]


def _under_1000(n):
    parts = []
    if n >= 100:
        parts.append(ONES[n // 100] + " hundred")
        n %= 100
    if n >= 20:
        word = TENS[n // 10]
        if n % 10:
            word += "-" + ONES[n % 10]
        parts.append(word)
    elif n > 0:
        parts.append(ONES[n])
    return " ".join(parts)


def _num_to_words(n):
    if n == 0:
        return "zero"
    groups = []
    scales = [("", 1), ("thousand", 10**3), ("million", 10**6),
              ("billion", 10**9), ("trillion", 10**12)]
    for name, value in reversed(scales):
        if n >= value:
            count = n // value
            n %= value
            groups.append(_under_1000(count) + (" " + name if name else ""))
    return " ".join(groups)


def price_label(cents):
    """Return a human-readable price label for an amount given in integer cents."""
    cents = int(cents)
    sign = "negative " if cents < 0 else ""
    cents = abs(cents)
    dollars, rem = divmod(cents, 100)

    parts = []
    if dollars:
        word = _num_to_words(dollars)
        parts.append(word + (" dollar" if dollars == 1 else " dollars"))
    if rem:
        word = _num_to_words(rem)
        parts.append(word + (" cent" if rem == 1 else " cents"))
    if not parts:
        parts = ["zero dollars"]
    return sign + " and ".join(parts)
